Item.method_code:
string currentSourceId = this.getProperty("source_id");
Item latestEndpointItem = this.newItem("cws_EndpointConfiguration", "get");
latestEndpointItem.setProperty("source_id", currentSourceId);
latestEndpointItem.setAttribute("select", "version");
latestEndpointItem.setAttribute("order_by", "version desc");
latestEndpointItem.setAttribute("maxRecords", "1");
latestEndpointItem = latestEndpointItem.apply();

if (latestEndpointItem.isEmpty()) {
  this.setProperty("version", "1");
  return this;
}

int previousVersion = int.Parse(latestEndpointItem.getProperty("version"), CultureInfo.InvariantCulture);
int nextVersion = previousVersion + 1;

this.setProperty("version", nextVersion.ToString(CultureInfo.InvariantCulture));
return this;
